  UNION ALL SELECT 5 AS sort_order, 'INDICES VALIDOS' AS verificacao, '=' AS regra, 31 AS esperado, (SELECT COUNT(*) FROM all_indexes WHERE owner = 'OPENRISOW' AND status = 'VALID' AND index_name IN ('IX_TBSDEV_PFEA_FEA', 'IX_TBSDEV_PENV_ENV', 'IX_TBSDEV_PSCR_SCR', 'IX_TBSDEV_SENV_ENV', 'IX_TBSDEV_USR_PRF', 'IX_TBSDEV_SPRM_PRM',
