      'IX_TBSDEV_TOUT_WRITE', 'IX_TBSDEV_IUP_ENV', 'IX_TBSDEV_IUP_SCR', 'IX_TBSDEV_IUP_CRT', 'IX_TBSDEV_IDL_PEND', 'IX_TBSDEV_ILS_ENV',
      'IX_TBSDEV_ILS_SCR')) AS encontrado FROM DUAL
  UNION ALL SELECT 6 AS sort_order, 'OBJETOS INVALIDOS' AS verificacao, '=' AS regra, 0 AS esperado, (SELECT COUNT(*) FROM all_objects WHERE owner = 'OPENRISOW' AND status = 'INVALID' AND object_name IN ('TBSDEV_ENVIRONMENTS', 'TBSDEV_PROFILES', 'TBSDEV_FEATURES', 'TBSDEV_PROFILE_FEATURE', 'TBSDEV_PROFILE_ENV', 'TBSDEV_SCRIPTS',
      'TBSDEV_PROFILE_SCRIPT', 'TBSDEV_SCRIPT_ENV', 'TBSDEV_USERS', 'TBSDEV_PARAMETERS', 'TBSDEV_SCRIPT_PARAM', 'TBSDEV_SCHEDULES',
      'TBSDEV_TICKETS', 'TBSDEV_TICKET_ANSWER', 'TBSDEV_AGENTS', 'TBSDEV_AUDIT', 'TBSDEV_CONTROL', 'TBSDEV_TICKET_OUTPUT',
      'TBSDEV_INPUT_UPLOAD', 'TBSDEV_INPUT_DELIVERY', 'TBSDEV_INPUT_LISTING', 'SQ_TBSDEV_ENVIRONMENTS', 'SQ_TBSDEV_PROFILES', 'SQ_TBSDEV_FEATURES',
      'SQ_TBSDEV_PROFILE_FEATURE', 'SQ_TBSDEV_PROFILE_ENV', 'SQ_TBSDEV_SCRIPTS', 'SQ_TBSDEV_PROFILE_SCRIPT', 'SQ_TBSDEV_SCRIPT_ENV', 'SQ_TBSDEV_USERS',
      'SQ_TBSDEV_PARAMETERS', 'SQ_TBSDEV_SCRIPT_PARAM', 'SQ_TBSDEV_SCHEDULES', 'SQ_TBSDEV_TICKETS', 'SQ_TBSDEV_TICKET_ANSWER', 'SQ_TBSDEV_AGENTS',
      'SQ_TBSDEV_AUDIT', 'SQ_TBSDEV_CONTROL', 'SQ_TBSDEV_TICKET_OUTPUT', 'SQ_TBSDEV_INPUT_UPLOAD', 'SQ_TBSDEV_INPUT_DELIVERY', 'SQ_TBSDEV_INPUT_LISTING',
      'TR_TBSDEV_ENV_BI', 'TR_TBSDEV_ENV_BU', 'TR_TBSDEV_PRF_BI', 'TR_TBSDEV_FEA_BI', 'TR_TBSDEV_PFEA_BI', 'TR_TBSDEV_PENV_BI',
      'TR_TBSDEV_SCR_BI', 'TR_TBSDEV_PSCR_BI', 'TR_TBSDEV_SENV_BI', 'TR_TBSDEV_USR_BI', 'TR_TBSDEV_USR_BU', 'TR_TBSDEV_PRM_BI',
      'TR_TBSDEV_SPRM_BI', 'TR_TBSDEV_SCH_BI', 'TR_TBSDEV_TCK_BI', 'TR_TBSDEV_TANS_BI', 'TR_TBSDEV_AGT_BI', 'TR_TBSDEV_AUD_BI',
      'TR_TBSDEV_CTL_BI', 'TR_TBSDEV_TOUT_BI', 'TR_TBSDEV_IUP_BI', 'TR_TBSDEV_IDL_BI', 'TR_TBSDEV_ILS_BI', 'IX_TBSDEV_PFEA_FEA',
      'IX_TBSDEV_PENV_ENV', 'IX_TBSDEV_PSCR_SCR', 'IX_TBSDEV_SENV_ENV', 'IX_TBSDEV_USR_PRF', 'IX_TBSDEV_SPRM_PRM', 'IX_TBSDEV_SCH_SCR',
      'IX_TBSDEV_SCH_USR', 'IX_TBSDEV_SCH_ENV', 'IX_TBSDEV_SCH_NEXT', 'IX_TBSDEV_TCK_SCR', 'IX_TBSDEV_TCK_ENV', 'IX_TBSDEV_TCK_USR',
      'IX_TBSDEV_TCK_PAR', 'IX_TBSDEV_TCK_SCH', 'IX_TBSDEV_TCK_CRT', 'IX_TBSDEV_TCK_HIST', 'IX_TBSDEV_TCK_QUEUE', 'IX_TBSDEV_TCK_RUN',
      'IX_TBSDEV_TCK_OCCUR', 'IX_TBSDEV_TANS_PRM', 'IX_TBSDEV_AUD_CRT', 'IX_TBSDEV_AUD_ENT', 'IX_TBSDEV_AUD_ACTOR', 'IX_TBSDEV_TOUT_WRITE',
      'IX_TBSDEV_IUP_ENV', 'IX_TBSDEV_IUP_SCR', 'IX_TBSDEV_IUP_CRT', 'IX_TBSDEV_IDL_PEND', 'IX_TBSDEV_ILS_ENV', 'IX_TBSDEV_ILS_SCR')) AS encontrado FROM DUAL
  UNION ALL SELECT 7 AS sort_order, 'GRANTS A PUBLIC' AS verificacao, '=' AS regra, 0 AS esperado, (SELECT COUNT(*) FROM all_tab_privs WHERE table_schema = 'OPENRISOW' AND grantee = 'PUBLIC' AND table_name IN ('TBSDEV_ENVIRONMENTS', 'TBSDEV_PROFILES', 'TBSDEV_FEATURES', 'TBSDEV_PROFILE_FEATURE', 'TBSDEV_PROFILE_ENV', 'TBSDEV_SCRIPTS',
      'TBSDEV_PROFILE_SCRIPT', 'TBSDEV_SCRIPT_ENV', 'TBSDEV_USERS', 'TBSDEV_PARAMETERS', 'TBSDEV_SCRIPT_PARAM', 'TBSDEV_SCHEDULES',
      'TBSDEV_TICKETS', 'TBSDEV_TICKET_ANSWER', 'TBSDEV_AGENTS', 'TBSDEV_AUDIT', 'TBSDEV_CONTROL', 'TBSDEV_TICKET_OUTPUT',
      'TBSDEV_INPUT_UPLOAD', 'TBSDEV_INPUT_DELIVERY', 'TBSDEV_INPUT_LISTING', 'SQ_TBSDEV_ENVIRONMENTS', 'SQ_TBSDEV_PROFILES', 'SQ_TBSDEV_FEATURES',
      'SQ_TBSDEV_PROFILE_FEATURE', 'SQ_TBSDEV_PROFILE_ENV', 'SQ_TBSDEV_SCRIPTS', 'SQ_TBSDEV_PROFILE_SCRIPT', 'SQ_TBSDEV_SCRIPT_ENV', 'SQ_TBSDEV_USERS',
      'SQ_TBSDEV_PARAMETERS', 'SQ_TBSDEV_SCRIPT_PARAM', 'SQ_TBSDEV_SCHEDULES', 'SQ_TBSDEV_TICKETS', 'SQ_TBSDEV_TICKET_ANSWER', 'SQ_TBSDEV_AGENTS',
      'SQ_TBSDEV_AUDIT', 'SQ_TBSDEV_CONTROL', 'SQ_TBSDEV_TICKET_OUTPUT', 'SQ_TBSDEV_INPUT_UPLOAD', 'SQ_TBSDEV_INPUT_DELIVERY', 'SQ_TBSDEV_INPUT_LISTING')) AS encontrado FROM DUAL
)
SELECT CASE WHEN COUNT(*) = 0 THEN 'OK: nenhuma falha'
            ELSE 'FALHA: ' || COUNT(*) || ' verificacao(oes) divergente(s)' END AS resumo
  FROM chk
 WHERE NOT ((regra = '=' AND encontrado = esperado) OR (regra = '>=' AND encontrado >= esperado))
    OR encontrado IS NULL;

PROMPT ==============================================================================
PROMPT 2. VERSAO DO ESQUEMA E MINIMO DE LINHAS DO SEED
PROMPT (se as tabelas nao existirem, esta secao falha com ORA-00942: veja a secao 1)
PROMPT ==============================================================================
WITH chk AS (
  SELECT 10 AS sort_order, 'VERSAO DO ESQUEMA' AS verificacao, '=' AS regra, 1 AS esperado, (SELECT MAX(schema_version) FROM openrisow.tbsdev_control) AS encontrado FROM DUAL
  UNION ALL SELECT 11 AS sort_order, 'LINHAS TBSDEV_ENVIRONMENTS' AS verificacao, '>=' AS regra, 5 AS esperado, (SELECT COUNT(*) FROM openrisow.tbsdev_environments) AS encontrado FROM DUAL
  UNION ALL SELECT 12 AS sort_order, 'LINHAS TBSDEV_PROFILES' AS verificacao, '>=' AS regra, 3 AS esperado, (SELECT COUNT(*) FROM openrisow.tbsdev_profiles) AS encontrado FROM DUAL
  UNION ALL SELECT 13 AS sort_order, 'LINHAS TBSDEV_FEATURES' AS verificacao, '>=' AS regra, 14 AS esperado, (SELECT COUNT(*) FROM openrisow.tbsdev_features) AS encontrado FROM DUAL
  UNION ALL SELECT 14 AS sort_order, 'LINHAS TBSDEV_PROFILE_FEATURE' AS verificacao, '>=' AS regra, 22 AS esperado, (SELECT COUNT(*) FROM openrisow.tbsdev_profile_feature) AS encontrado FROM DUAL
  UNION ALL SELECT 15 AS sort_order, 'LINHAS TBSDEV_PROFILE_ENV' AS verificacao, '>=' AS regra, 15 AS esperado, (SELECT COUNT(*) FROM openrisow.tbsdev_profile_env) AS encontrado FROM DUAL
  UNION ALL SELECT 16 AS sort_order, 'LINHAS TBSDEV_SCRIPTS' AS verificacao, '>=' AS regra, 14 AS esperado, (SELECT COUNT(*) FROM openrisow.tbsdev_scripts) AS encontrado FROM DUAL
  UNION ALL SELECT 17 AS sort_order, 'LINHAS TBSDEV_PROFILE_SCRIPT' AS verificacao, '>=' AS regra, 42 AS esperado, (SELECT COUNT(*) FROM openrisow.tbsdev_profile_script) AS encontrado FROM DUAL
  UNION ALL SELECT 18 AS sort_order, 'LINHAS TBSDEV_SCRIPT_ENV' AS verificacao, '>=' AS regra, 70 AS esperado, (SELECT COUNT(*) FROM openrisow.tbsdev_script_env) AS encontrado FROM DUAL
  UNION ALL SELECT 19 AS sort_order, 'LINHAS TBSDEV_USERS' AS verificacao, '>=' AS regra, 3 AS esperado, (SELECT COUNT(*) FROM openrisow.tbsdev_users) AS encontrado FROM DUAL
  UNION ALL SELECT 20 AS sort_order, 'LINHAS TBSDEV_PARAMETERS' AS verificacao, '>=' AS regra, 19 AS esperado, (SELECT COUNT(*) FROM openrisow.tbsdev_parameters) AS encontrado FROM DUAL
  UNION ALL SELECT 21 AS sort_order, 'LINHAS TBSDEV_SCRIPT_PARAM' AS verificacao, '>=' AS regra, 38 AS esperado, (SELECT COUNT(*) FROM openrisow.tbsdev_script_param) AS encontrado FROM DUAL
  UNION ALL SELECT 22 AS sort_order, 'LINHAS TBSDEV_SCHEDULES' AS verificacao, '>=' AS regra, 0 AS esperado, (SELECT COUNT(*) FROM openrisow.tbsdev_schedules) AS encontrado FROM DUAL
  UNION ALL SELECT 23 AS sort_order, 'LINHAS TBSDEV_TICKETS' AS verificacao, '>=' AS regra, 0 AS esperado, (SELECT COUNT(*) FROM openrisow.tbsdev_tickets) AS encontrado FROM DUAL
  UNION ALL SELECT 24 AS sort_order, 'LINHAS TBSDEV_TICKET_ANSWER' AS verificacao, '>=' AS regra, 0 AS esperado, (SELECT COUNT(*) FROM openrisow.tbsdev_ticket_answer) AS encontrado FROM DUAL
  UNION ALL SELECT 25 AS sort_order, 'LINHAS TBSDEV_AGENTS' AS verificacao, '>=' AS regra, 0 AS esperado, (SELECT COUNT(*) FROM openrisow.tbsdev_agents) AS encontrado FROM DUAL
  UNION ALL SELECT 26 AS sort_order, 'LINHAS TBSDEV_AUDIT' AS verificacao, '>=' AS regra, 0 AS esperado, (SELECT COUNT(*) FROM openrisow.tbsdev_audit) AS encontrado FROM DUAL
  UNION ALL SELECT 27 AS sort_order, 'LINHAS TBSDEV_CONTROL' AS verificacao, '>=' AS regra, 1 AS esperado, (SELECT COUNT(*) FROM openrisow.tbsdev_control) AS encontrado FROM DUAL
  UNION ALL SELECT 28 AS sort_order, 'LINHAS TBSDEV_TICKET_OUTPUT' AS verificacao, '>=' AS regra, 0 AS esperado, (SELECT COUNT(*) FROM openrisow.tbsdev_ticket_output) AS encontrado FROM DUAL
  UNION ALL SELECT 29 AS sort_order, 'LINHAS TBSDEV_INPUT_UPLOAD' AS verificacao, '>=' AS regra, 0 AS esperado, (SELECT COUNT(*) FROM openrisow.tbsdev_input_upload) AS encontrado FROM DUAL
  UNION ALL SELECT 30 AS sort_order, 'LINHAS TBSDEV_INPUT_DELIVERY' AS verificacao, '>=' AS regra, 0 AS esperado, (SELECT COUNT(*) FROM openrisow.tbsdev_input_delivery) AS encontrado FROM DUAL
  UNION ALL SELECT 31 AS sort_order, 'LINHAS TBSDEV_INPUT_LISTING' AS verificacao, '>=' AS regra, 0 AS esperado, (SELECT COUNT(*) FROM openrisow.tbsdev_input_listing) AS encontrado FROM DUAL
)
SELECT verificacao, regra || ' ' || esperado AS esperado, encontrado,
       CASE WHEN (regra = '=' AND encontrado = esperado) OR (regra = '>=' AND encontrado >= esperado)
            THEN 'OK' ELSE 'FALHA' END AS resultado
  FROM chk ORDER BY sort_order;

WITH chk AS (
  SELECT 10 AS sort_order, 'VERSAO DO ESQUEMA' AS verificacao, '=' AS regra, 1 AS esperado, (SELECT MAX(schema_version) FROM openrisow.tbsdev_control) AS encontrado FROM DUAL
  UNION ALL SELECT 11 AS sort_order, 'LINHAS TBSDEV_ENVIRONMENTS' AS verificacao, '>=' AS regra, 5 AS esperado, (SELECT COUNT(*) FROM openrisow.tbsdev_environments) AS encontrado FROM DUAL
  UNION ALL SELECT 12 AS sort_order, 'LINHAS TBSDEV_PROFILES' AS verificacao, '>=' AS regra, 3 AS esperado, (SELECT COUNT(*) FROM openrisow.tbsdev_profiles) AS encontrado FROM DUAL
  UNION ALL SELECT 13 AS sort_order, 'LINHAS TBSDEV_FEATURES' AS verificacao, '>=' AS regra, 14 AS esperado, (SELECT COUNT(*) FROM openrisow.tbsdev_features) AS encontrado FROM DUAL
  UNION ALL SELECT 14 AS sort_order, 'LINHAS TBSDEV_PROFILE_FEATURE' AS verificacao, '>=' AS regra, 22 AS esperado, (SELECT COUNT(*) FROM openrisow.tbsdev_profile_feature) AS encontrado FROM DUAL
  UNION ALL SELECT 15 AS sort_order, 'LINHAS TBSDEV_PROFILE_ENV' AS verificacao, '>=' AS regra, 15 AS esperado, (SELECT COUNT(*) FROM openrisow.tbsdev_profile_env) AS encontrado FROM DUAL
  UNION ALL SELECT 16 AS sort_order, 'LINHAS TBSDEV_SCRIPTS' AS verificacao, '>=' AS regra, 14 AS esperado, (SELECT COUNT(*) FROM openrisow.tbsdev_scripts) AS encontrado FROM DUAL
  UNION ALL SELECT 17 AS sort_order, 'LINHAS TBSDEV_PROFILE_SCRIPT' AS verificacao, '>=' AS regra, 42 AS esperado, (SELECT COUNT(*) FROM openrisow.tbsdev_profile_script) AS encontrado FROM DUAL
  UNION ALL SELECT 18 AS sort_order, 'LINHAS TBSDEV_SCRIPT_ENV' AS verificacao, '>=' AS regra, 70 AS esperado, (SELECT COUNT(*) FROM openrisow.tbsdev_script_env) AS encontrado FROM DUAL
  UNION ALL SELECT 19 AS sort_order, 'LINHAS TBSDEV_USERS' AS verificacao, '>=' AS regra, 3 AS esperado, (SELECT COUNT(*) FROM openrisow.tbsdev_users) AS encontrado FROM DUAL
  UNION ALL SELECT 20 AS sort_order, 'LINHAS TBSDEV_PARAMETERS' AS verificacao, '>=' AS regra, 19 AS esperado, (SELECT COUNT(*) FROM openrisow.tbsdev_parameters) AS encontrado FROM DUAL
  UNION ALL SELECT 21 AS sort_order, 'LINHAS TBSDEV_SCRIPT_PARAM' AS verificacao, '>=' AS regra, 38 AS esperado, (SELECT COUNT(*) FROM openrisow.tbsdev_script_param) AS encontrado FROM DUAL
  UNION ALL SELECT 22 AS sort_order, 'LINHAS TBSDEV_SCHEDULES' AS verificacao, '>=' AS regra, 0 AS esperado, (SELECT COUNT(*) FROM openrisow.tbsdev_schedules) AS encontrado FROM DUAL
  UNION ALL SELECT 23 AS sort_order, 'LINHAS TBSDEV_TICKETS' AS verificacao, '>=' AS regra, 0 AS esperado, (SELECT COUNT(*) FROM openrisow.tbsdev_tickets) AS encontrado FROM DUAL
  UNION ALL SELECT 24 AS sort_order, 'LINHAS TBSDEV_TICKET_ANSWER' AS verificacao, '>=' AS regra, 0 AS esperado, (SELECT COUNT(*) FROM openrisow.tbsdev_ticket_answer) AS encontrado FROM DUAL
  UNION ALL SELECT 25 AS sort_order, 'LINHAS TBSDEV_AGENTS' AS verificacao, '>=' AS regra, 0 AS esperado, (SELECT COUNT(*) FROM openrisow.tbsdev_agents) AS encontrado FROM DUAL
  UNION ALL SELECT 26 AS sort_order, 'LINHAS TBSDEV_AUDIT' AS verificacao, '>=' AS regra, 0 AS esperado, (SELECT COUNT(*) FROM openrisow.tbsdev_audit) AS encontrado FROM DUAL
  UNION ALL SELECT 27 AS sort_order, 'LINHAS TBSDEV_CONTROL' AS verificacao, '>=' AS regra, 1 AS esperado, (SELECT COUNT(*) FROM openrisow.tbsdev_control) AS encontrado FROM DUAL
  UNION ALL SELECT 28 AS sort_order, 'LINHAS TBSDEV_TICKET_OUTPUT' AS verificacao, '>=' AS regra, 0 AS esperado, (SELECT COUNT(*) FROM openrisow.tbsdev_ticket_output) AS encontrado FROM DUAL
  UNION ALL SELECT 29 AS sort_order, 'LINHAS TBSDEV_INPUT_UPLOAD' AS verificacao, '>=' AS regra, 0 AS esperado, (SELECT COUNT(*) FROM openrisow.tbsdev_input_upload) AS encontrado FROM DUAL
  UNION ALL SELECT 30 AS sort_order, 'LINHAS TBSDEV_INPUT_DELIVERY' AS verificacao, '>=' AS regra, 0 AS esperado, (SELECT COUNT(*) FROM openrisow.tbsdev_input_delivery) AS encontrado FROM DUAL
  UNION ALL SELECT 31 AS sort_order, 'LINHAS TBSDEV_INPUT_LISTING' AS verificacao, '>=' AS regra, 0 AS esperado, (SELECT COUNT(*) FROM openrisow.tbsdev_input_listing) AS encontrado FROM DUAL
)
SELECT CASE WHEN COUNT(*) = 0 THEN 'OK: nenhuma falha'
            ELSE 'FALHA: ' || COUNT(*) || ' verificacao(oes) divergente(s)' END AS resumo
  FROM chk
 WHERE NOT ((regra = '=' AND encontrado = esperado) OR (regra = '>=' AND encontrado >= esperado))
    OR encontrado IS NULL;

PROMPT ==============================================================================
PROMPT 3. USUARIOS E PERFIS (sem hash de senha)
PROMPT ==============================================================================
COLUMN login FORMAT A20
COLUMN name FORMAT A30
COLUMN perfil FORMAT A20
COLUMN admin FORMAT A5
COLUMN active FORMAT A5
COLUMN senha_definida FORMAT A14
SELECT u.id, u.login, u.name, p.name AS perfil, p.is_admin AS admin, u.active,
       CASE WHEN u.password_hash IS NULL THEN 'N' ELSE 'Y' END AS senha_definida
  FROM openrisow.tbsdev_users u JOIN openrisow.tbsdev_profiles p ON p.id = u.profile_id
 ORDER BY u.id;

PROMPT ==============================================================================
PROMPT 4. SCRIPTS CADASTRADOS
PROMPT ==============================================================================
COLUMN name FORMAT A25
COLUMN interpreter FORMAT A13
COLUMN param_type FORMAT A10
COLUMN path_file FORMAT A70
SELECT id, name, interpreter, param_type, max_parallel_env AS paral, timeout_s AS tmout,
       active, path_file
  FROM openrisow.tbsdev_scripts
 ORDER BY id;

PROMPT ==============================================================================
PROMPT 5. ACESSO POR PERFIL (funcionalidades, ambientes e scripts liberados)
PROMPT ==============================================================================
COLUMN perfil FORMAT A20
SELECT p.name AS perfil, p.is_admin AS admin, p.active,
       (SELECT COUNT(*) FROM openrisow.tbsdev_profile_feature x WHERE x.profile_id = p.id) AS funcionalidades,
       (SELECT COUNT(*) FROM openrisow.tbsdev_profile_env x WHERE x.profile_id = p.id) AS environments,
       (SELECT COUNT(*) FROM openrisow.tbsdev_profile_script x WHERE x.profile_id = p.id) AS scripts
  FROM openrisow.tbsdev_profiles p
 ORDER BY p.name;

PROMPT ==============================================================================
PROMPT 6. GRANTS NOS OBJETOS DO SSS (README 11.1: so contas dos papeis; nunca PUBLIC)
PROMPT ==============================================================================
SET FEEDBACK ON
COLUMN grantee FORMAT A30
COLUMN privilege FORMAT A12
SELECT grantee, privilege, COUNT(*) AS objetos
  FROM all_tab_privs
 WHERE table_schema = 'OPENRISOW' AND table_name IN ('TBSDEV_ENVIRONMENTS', 'TBSDEV_PROFILES', 'TBSDEV_FEATURES', 'TBSDEV_PROFILE_FEATURE', 'TBSDEV_PROFILE_ENV', 'TBSDEV_SCRIPTS',
      'TBSDEV_PROFILE_SCRIPT', 'TBSDEV_SCRIPT_ENV', 'TBSDEV_USERS', 'TBSDEV_PARAMETERS', 'TBSDEV_SCRIPT_PARAM', 'TBSDEV_SCHEDULES',
      'TBSDEV_TICKETS', 'TBSDEV_TICKET_ANSWER', 'TBSDEV_AGENTS', 'TBSDEV_AUDIT', 'TBSDEV_CONTROL', 'TBSDEV_TICKET_OUTPUT',
      'TBSDEV_INPUT_UPLOAD', 'TBSDEV_INPUT_DELIVERY', 'TBSDEV_INPUT_LISTING', 'SQ_TBSDEV_ENVIRONMENTS', 'SQ_TBSDEV_PROFILES', 'SQ_TBSDEV_FEATURES',
      'SQ_TBSDEV_PROFILE_FEATURE', 'SQ_TBSDEV_PROFILE_ENV', 'SQ_TBSDEV_SCRIPTS', 'SQ_TBSDEV_PROFILE_SCRIPT', 'SQ_TBSDEV_SCRIPT_ENV', 'SQ_TBSDEV_USERS',
      'SQ_TBSDEV_PARAMETERS', 'SQ_TBSDEV_SCRIPT_PARAM', 'SQ_TBSDEV_SCHEDULES', 'SQ_TBSDEV_TICKETS', 'SQ_TBSDEV_TICKET_ANSWER', 'SQ_TBSDEV_AGENTS',
      'SQ_TBSDEV_AUDIT', 'SQ_TBSDEV_CONTROL', 'SQ_TBSDEV_TICKET_OUTPUT', 'SQ_TBSDEV_INPUT_UPLOAD', 'SQ_TBSDEV_INPUT_DELIVERY', 'SQ_TBSDEV_INPUT_LISTING')
 GROUP BY grantee, privilege
 ORDER BY grantee, privilege;
SET FEEDBACK OFF

PROMPT Fim da validacao do SSS.
EXIT;
